                'sector_id' => null,
            ],
        ];

        foreach ($indices as $data) {
            Asset::firstOrCreate(
                ['id' => $data['id']],
                [
                    'tv_id' => ! empty($data['tv_id']) ? $data['tv_id'] : null,
